const keywords = [
  'kebun',
  'pokok',
  'tanam',
  'baja',
  'tanaman',
  'fertigasi',
  'hidroponik',
  'kebun bandar',
  'pokok cili',
  'daun kuning'
];

const selectedKeyword = keywords[Math.floor(Math.random() * keywords.length)];
const config = $('Setup Configuration & Controls1').first().json;

return {
  json: {
    keyword: selectedKeyword,
    config: config
  }
};

const items = $input.first().json.data || [];
const config = $('Setup Configuration & Controls1').first().json;
const keywordInfo = $('Pick Random Niche Keyword1').first().json;

const staticData = $getWorkflowStaticData('global');
staticData.engagedPostIds = staticData.engagedPostIds || [];
staticData.engagedAuthors = staticData.engagedAuthors || {};

const candidates = [];
const nowMs = Date.now();
const cooldownMs = (config.authorCooldownHours || 72) * 60 * 60 * 1000;

// Prohibited sensitive / anti-spam keywords
const prohibitedKeywords = [
  'politik', 'PRU', 'kerajaan', 'subsidi', 'benci', 'jual', 'harta', 'kasino',
  'pinjaman', 'scam', 'racun rumput haram', 'saham'
];

for (const post of items) {
  if (!post.id || !post.text) continue;

  // 1. Post ID Duplicate Check
  if (staticData.engagedPostIds.includes(post.id)) continue;

  // 2. Own Post Check
  const usernameLower = (post.username || '').toLowerCase();
  if (usernameLower.includes('kebundata') || usernameLower.includes('robot.people') || usernameLower.includes('robot_people')) continue;

  // 3. Length Check
  if (post.text.trim().length < 25) continue;

  // 4. Prohibited Keyword Check
  const postLower = post.text.toLowerCase();
  if (prohibitedKeywords.some(kw => postLower.includes(kw))) continue;

  // 5. Author Cooldown Check (72 Hours)
  const lastEngaged = staticData.engagedAuthors[usernameLower];
  if (lastEngaged && (nowMs - lastEngaged < cooldownMs)) continue;

  candidates.push({
    json: {
      postId: post.id,
      postText: post.text,
      postUsername: post.username || 'Geng Kebun',
      matchedKeyword: keywordInfo.keyword,
      threadsUserId: config.threadsUserId,
      telegramChatId: config.telegramChatId,
      dryRun: config.dryRun,
      scoutThreshold: config.scoutThreshold,
      similarityThreshold: config.similarityThreshold
    }
  });

  // Limit to 1 candidate per schedule run for conservative pacing
  if (candidates.length >= 1) {
    break;
  }
}

if (candidates.length === 0) {
  return [{ json: { postId: "", postText: "", status: "NO_CANDIDATE_FOUND" } }];
}

return candidates;

