const candidate = $('Hard Exclusion Filters1').first().json;
const rawText = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '{}';
let scoutResult = {};

try {
  const cleanJson = rawText.replace(/```json/g, '').replace(/```/g, '').trim();
  scoutResult = JSON.parse(cleanJson);
} catch (e) {
  scoutResult = {
    decision: 'NO_REPLY',
    relevance_score: 0,
    conversation_score: 0,
    value_score: 0,
    risk_score: 100,
    confidence_score: 0,
    reason: 'Failed to parse Scout JSON output'
  };
}

const relevance = scoutResult.relevance_score || 0;
const conversation = scoutResult.conversation_score || 0;
const value = scoutResult.value_score || 0;
const confidence = scoutResult.confidence_score || 0;
const risk = scoutResult.risk_score || 0;

// Deterministic Score Calculation:
// base_score = (relevance * 0.30) + (conversation * 0.25) + (value * 0.25) + (confidence * 0.20)
const baseScore = (relevance * 0.30) + (conversation * 0.25) + (value * 0.25) + (confidence * 0.20);
const riskPenalty = risk * 0.50;
const finalScore = Math.max(0, Math.round(baseScore - riskPenalty));

const threshold = candidate.scoutThreshold || 75;
const qualified = (scoutResult.decision === 'REPLY') && (finalScore >= threshold) && (risk <= 20);

return [{
  json: {
    ...candidate,
    scoutDecision: scoutResult.decision || 'NO_REPLY',
    relevanceScore: relevance,
    conversationScore: conversation,
    valueScore: value,
    riskScore: risk,
    confidenceScore: confidence,
    finalScore: finalScore,
    scoutReason: scoutResult.reason || '',
    recommendedReplyType: scoutResult.recommended_reply_type || 'DIRECT_ADVICE',
    qualified: qualified
  }
}];

