const prev = $('Deterministic Opportunity Scoring1').first().json;
const stratRaw = $('Reply Strategist Agent (Gemini)1').first().json.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '{}';
const gateRaw = $input.first().json.candidates?.[0]?.content?.parts?.[0]?.text?.trim() || '{}';

let strat = {};
let gate = {};

try {
  strat = JSON.parse(stratRaw.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {}

try {
  gate = JSON.parse(gateRaw.replace(/```json/g, '').replace(/```/g, '').trim());
} catch (e) {}

const draftText = strat.draft || '';
const staticData = $getWorkflowStaticData('global');
staticData.recentDrafts = staticData.recentDrafts || [];

function getSimilarity(s1, s2) {
  if (!s1 || !s2) return 0;
  const pairs1 = getBigrams(s1.toLowerCase());
  const pairs2 = getBigrams(s2.toLowerCase());
  let union = pairs1.length + pairs2.length;
  let hit = 0;
  for (const p1 of pairs1) {
    for (let i = 0; i < pairs2.length; i++) {
      if (p1 === pairs2[i]) {
        hit++;
        pairs2.splice(i, 1);
        break;
      }
    }
  }
  return (2.0 * hit) / union;
}

function getBigrams(str) {
  const bigrams = [];
  for (let i = 0; i < str.length - 1; i++) {
    bigrams.push(str.substring(i, i + 2));
  }
  return bigrams;
}

function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

let isDuplicate = false;
const threshold = prev.similarityThreshold || 0.80;
for (const pastDraft of staticData.recentDrafts) {
  if (getSimilarity(draftText, pastDraft) > threshold) {
    isDuplicate = true;
    break;
  }
}

if (!isDuplicate && draftText) {
  staticData.recentDrafts.push(draftText);
  if (staticData.recentDrafts.length > 50) staticData.recentDrafts.shift();
}

const safetyApproved = gate.decision === 'APPROVE_FOR_HUMAN_REVIEW' && strat.decision === 'REPLY' && !isDuplicate;

return [{
  json: {
    ...prev,
    replyType: strat.reply_type || prev.recommendedReplyType,
    draftReply: draftText,
    safeDraftReply: escapeHtml(draftText),
    safePostText: escapeHtml(prev.postText),
    safetyDecision: gate.decision || 'REJECT',
    qualityScore: gate.quality_score || 0,
    isDuplicate: isDuplicate,
    safetyApproved: safetyApproved
  }
}];

const d = $input.first().json;
if (!/^\d+$/.test(String(d.postId || '')) || typeof d.draftReply !== 'string' || !d.draftReply.trim() || !d.telegramChatId) throw new Error('Incomplete approval draft');
if (d.safetyApproved !== true) throw new Error('Draft has not passed safety review');
return [{json:d}];

const row=$input.first().json;
const draft=$('Validate Draft Before Storage').first().json;
if (!/^\d+$/.test(String(row.id || '')) || row.post_id !== draft.postId || row.draft_reply !== draft.draftReply) throw new Error('Stored approval does not match draft');
if (!row.approval_expires_at || !Number.isFinite(Date.parse(row.approval_expires_at)) || Date.parse(row.approval_expires_at)<=Date.now()) throw new Error('Missing or expired approval deadline');
return [{json:{...draft,approvalId:row.id,draftReply:row.draft_reply,postId:row.post_id}}];
